import {
  DatabaseIntrospector,
  DatabaseMetadata,
  DatabaseMetadataOptions,
  SchemaMetadata,
  TableMetadata,
} from "kysely";
import { DEFAULT_MIGRATION_LOCK_TABLE, DEFAULT_MIGRATION_TABLE } from "kysely";
import { Kysely } from "kysely";
import { sql } from "kysely";

export class PostgresIntrospector implements DatabaseIntrospector {
  readonly #db: Kysely<any>;

  constructor(db: Kysely<any>) {
    this.#db = db;
  }

  async getSchemas(): Promise<SchemaMetadata[]> {
    let rawSchemas = await this.#db
      .selectFrom("pg_catalog.pg_namespace")
      .select("nspname")
      .$castTo<RawSchemaMetadata>()
      .execute();

    return rawSchemas.map((it) => ({ name: it.nspname }));
  }

  async getTables(
    options: DatabaseMetadataOptions = { withInternalKyselyTables: false }
  ): Promise<TableMetadata[]> {
    let query = this.#db
      // column
      .selectFrom("pg_catalog.pg_attribute as a")
      // table
      .innerJoin("pg_catalog.pg_class as c", "a.attrelid", "c.oid")
      // table schema
      .innerJoin("pg_catalog.pg_namespace as ns", "c.relnamespace", "ns.oid")
      // column data type
      .innerJoin("pg_catalog.pg_type as typ", "a.atttypid", "typ.oid")
      // column data type schema
      .innerJoin(
        "pg_catalog.pg_namespace as dtns",
        "typ.typnamespace",
        "dtns.oid"
      )
      .select([
        "a.attname as column",
        "a.attnotnull as not_null",
        "a.atthasdef as has_default",
        "c.relname as table",
        sql<string>`case when c.relkind = 'v' then true else false end`.as(
          "is_view"
        ),
        "ns.nspname as schema",
        "typ.typname as type",
        "dtns.nspname as type_schema",

        // Detect if the column is auto incrementing by finding the sequence
        // that is created for `serial` and `bigserial` columns.
        this.#db
          .selectFrom("pg_class")
          .select(sql`true`.as("auto_incrementing"))
          // Make sure the sequence is in the same schema as the table.
          .whereRef("relnamespace", "=", "c.relnamespace")
          .where("relkind", "=", "S")
          .where("relname", "=", sql`c.relname || '_' || a.attname || '_seq'`)
          .as("auto_incrementing"),
      ])
      // r == normal table
      .where("c.relkind", "in", ["r", "v"])
      .where("ns.nspname", "!~", "^pg_")
      .where("ns.nspname", "!=", "information_schema")
      // No system columns
      .where("a.attnum", ">=", 0)
      .where("a.attisdropped", "!=", true)
      .orderBy("ns.nspname")
      .orderBy("c.relname")
      .orderBy("a.attnum")
      .$castTo<RawColumnMetadata>();

    if (!options.withInternalKyselyTables) {
      query = query
        .where("c.relname", "!=", DEFAULT_MIGRATION_TABLE)
        .where("c.relname", "!=", DEFAULT_MIGRATION_LOCK_TABLE);
    }

    const rawColumns = await query.execute();
    return this.#parseTableMetadata(rawColumns);
  }

  async getMetadata(
    options?: DatabaseMetadataOptions
  ): Promise<DatabaseMetadata> {
    return {
      tables: await this.getTables(options),
    };
  }

  #parseTableMetadata(columns: RawColumnMetadata[]): TableMetadata[] {
    return columns.reduce<TableMetadata[]>((tables, it) => {
      let table = tables.find(
        (tbl) => tbl.name === it.table && tbl.schema === it.schema
      );

      if (!table) {
        table = Object.freeze({
          name: it.table,
          isView: it.is_view,
          schema: it.schema,
          columns: [],
        });

        tables.push(table);
      }

      table.columns.push(
        Object.freeze({
          name: it.column,
          dataType: it.type,
          dataTypeSchema: it.type_schema,
          isNullable: !it.not_null,
          isAutoIncrementing: !!it.auto_incrementing,
          hasDefaultValue: it.has_default,
        })
      );

      return tables;
    }, []);
  }
}

interface RawSchemaMetadata {
  nspname: string;
}

interface RawColumnMetadata {
  column: string;
  table: string;
  is_view: boolean;
  schema: string;
  not_null: boolean;
  has_default: boolean;
  type: string;
  type_schema: string;
  auto_incrementing: boolean | null;
}

import {
  Driver,
  MysqlAdapter,
  MysqlIntrospector,
  PostgresAdapter,
  Kysely,
  QueryCompiler,
  Dialect,
  DatabaseIntrospector,
} from "kysely";
import { DataApiDriver, DataApiDriverConfig } from "./data-api-driver.js";
import {
  PostgresDataApiQueryCompiler,
  MysqlDataApiQueryCompiler,
} from "./data-api-query-compiler.js";
import { PostgresIntrospector } from "./postgres-introspector.js";

type DataApiDialectConfig = {
  mode: "postgres" | "mysql";
  driver: DataApiDriverConfig;
};

export class DataApiDialect implements Dialect {
  readonly #config: DataApiDialectConfig;

  constructor(config: DataApiDialectConfig) {
    this.#config = config;
  }

  createAdapter() {
    if (this.#config.mode === "postgres") return new PostgresAdapter();
    if (this.#config.mode === "mysql") return new MysqlAdapter();

    throw new Error("Unknown mode " + this.#config.mode);
  }

  createDriver(): Driver {
    return new DataApiDriver(this.#config.driver);
  }

  createQueryCompiler(): QueryCompiler {
    if (this.#config.mode === "postgres")
      return new PostgresDataApiQueryCompiler();
    if (this.#config.mode === "mysql") return new MysqlDataApiQueryCompiler();

    throw new Error("Unknown mode " + this.#config.mode);
  }

  createIntrospector(db: Kysely<unknown>): DatabaseIntrospector {
    if (this.#config.mode === "postgres") return new PostgresIntrospector(db);
    if (this.#config.mode === "mysql") return new MysqlIntrospector(db);

    throw new Error("Unknown mode " + this.#config.mode);
  }
}

import { SqlParameter } from "@aws-sdk/client-rds-data";
import { MysqlQueryCompiler, PostgresQueryCompiler } from "kysely";

export class PostgresDataApiQueryCompiler extends PostgresQueryCompiler {
  protected override appendValue(value: unknown) {
    const name = this.numParameters;
    this.append(this.getCurrentParameterPlaceholder());
    this.addParameter({
      name: name.toString(),
      ...serialize(value),
    });
  }

  protected override getCurrentParameterPlaceholder() {
    return ":" + this.numParameters;
  }
}

export class MysqlDataApiQueryCompiler extends MysqlQueryCompiler {
  protected override appendValue(value: unknown) {
    const name = this.numParameters;
    this.append(this.getCurrentParameterPlaceholder());
    this.addParameter({
      name: name.toString(),
      ...serialize(value),
    });
  }

  protected override getCurrentParameterPlaceholder() {
    return ":" + this.numParameters;
  }
}

function serialize(value: unknown): Pick<SqlParameter, "typeHint" | "value"> {
  switch (typeof value) {
  case "bigint":
    return { value: { doubleValue: Number(value) } };
  case "boolean":
    return { value: { booleanValue: value } };
  case "number":
    if (Number.isInteger(value))
      return { value: { longValue: value } };
    else
      return { value: { doubleValue: value } };
  case "object":
    if (value == null)
      return { value: { isNull: true }};
    else if (Buffer.isBuffer(value))
      return { value: { blobValue: value } };
    else if (value instanceof Date)
      return {
        typeHint: "TIMESTAMP",
        value: { stringValue: fixISOString(value.toISOString()) },
      };
    else if ((value as RSU)?.value && isValueObject((value as RSU).value as RSU)) {
      if (
        (value as RSU).typeHint && ((value as RSU).value as RSU).stringValue
        && typeof ((value as RSU).value as RSU).stringValue === "string"
      )
        ((value as RSU).value as RSU).stringValue = fixStringValue(
          (value as RSS).typeHint as SqlParameter["typeHint"],
          ((value as RSU).value as RSS).stringValue,
        );
      return value;
    }
    else
      break;
  case "string":
    return {
      value: { stringValue: value },
    };
  }

  throw new QueryCompilerError("Could not serialize value");
}

function fixStringValue(typeHint: SqlParameter["typeHint"], value: string) {
  switch (typeHint) {
  case "DATE":
    return parseToISOString(value).slice(0, 10);
  case "TIME":
    if (value.match(/^\d{4}-\d{2}-\d{2}/)) {
      return parseToISOString(value).slice(11, 23);
    }
    return fixTimeString(value);
  case "TIMESTAMP":
    return fixISOString(parseToISOString(value));
  }
  return value;
}

function fixTimeString(s: string) {
  const elements = (s || "00:00:00").split(":");
  while (elements.length < 3) {
    elements.push("00");
  }
  return elements.join(":").slice(0, 12);
}

function fixISOString(s: string) {
  return s.replace("T", " ").slice(0, 23);
}

function parseToISOString(s: string) {
  return new Date(Date.parse(s)).toISOString();
}

function isValueObject(value: Record<string, unknown>) {
  for (const key of primitiveKeys) {
    if (value[key]) {
      return true;
    }
  }
  if (value.arrayValue) {
    for (const key of arrayKeys) {
      if ((value.arrayValue as Record<string, unknown>)?.[key]) {
        return true;
      }
    }
  }
  return false;
}

class QueryCompilerError extends Error {
  constructor(message: string) {
    super(message);
    this.name = QueryCompilerError.name;
  }
}

const arrayKeys = ["booleanValues", "doubleValues", "longValues", "stringValues"];
const primitiveKeys = ["blobValue", "booleanValue", "doubleValue", "isNull", "longValue", "stringValue"];

type RSS = Record<string, string>;
type RSU = Record<string, unknown>;

import { ArrayValue, RDSData, SqlParameter } from "@aws-sdk/client-rds-data";
import { CompiledQuery, DatabaseConnection, Driver, QueryResult } from "kysely";

export type DataApiDriverConfig = {
  client: RDSData;
  secretArn: string;
  resourceArn: string;
  database: string;
};

export class DataApiDriver implements Driver {
  #config: DataApiDriverConfig;

  constructor(config: DataApiDriverConfig) {
    this.#config = config;
  }

  async init(): Promise<void> {
    // do nothing
  }

  async acquireConnection(): Promise<DatabaseConnection> {
    return new DataApiConnection(this.#config);
  }

  async beginTransaction(conn: DataApiConnection) {
    await conn.beginTransaction();
  }

  async commitTransaction(conn: DataApiConnection) {
    await conn.commitTransaction();
  }

  async rollbackTransaction(conn: DataApiConnection) {
    await conn.rollbackTransaction();
  }

  async releaseConnection(_connection: DatabaseConnection): Promise<void> {
    // do nothing
  }

  async destroy(): Promise<void> {
    // do nothing
  }
}

class DataApiConnection implements DatabaseConnection {
  #config: DataApiDriverConfig;
  #transactionId?: string;

  constructor(config: DataApiDriverConfig) {
    this.#config = config;
  }

  public async beginTransaction() {
    const r = await this.#config.client.beginTransaction({
      secretArn: this.#config.secretArn,
      resourceArn: this.#config.resourceArn,
      database: this.#config.database,
    });
    this.#transactionId = r.transactionId;
  }

  public async commitTransaction() {
    if (!this.#transactionId)
      throw new Error("Cannot commit a transaction before creating it");
    await this.#config.client.commitTransaction({
      secretArn: this.#config.secretArn,
      resourceArn: this.#config.resourceArn,
      transactionId: this.#transactionId,
    });
  }

  public async rollbackTransaction() {
    if (!this.#transactionId)
      throw new Error("Cannot rollback a transaction before creating it");
    await this.#config.client.rollbackTransaction({
      secretArn: this.#config.secretArn,
      resourceArn: this.#config.resourceArn,
      transactionId: this.#transactionId,
    });
  }

  async executeQuery<O>(compiledQuery: CompiledQuery): Promise<QueryResult<O>> {
    const r = await this.#config.client.executeStatement({
      transactionId: this.#transactionId,
      secretArn: this.#config.secretArn,
      resourceArn: this.#config.resourceArn,
      sql: compiledQuery.sql,
      parameters: compiledQuery.parameters as SqlParameter[],
      database: this.#config.database,
      includeResultMetadata: true,
    });
    if (!r.columnMetadata) {
      const numAffectedRows = BigInt(r.numberOfRecordsUpdated || 0);

      return {
        // @ts-ignore replaces `QueryResult.numUpdatedOrDeletedRows` in kysely >= 0.23
        // following https://github.com/koskimas/kysely/pull/188
        numAffectedRows,
        // deprecated in kysely >= 0.23, keep for backward compatibility.
        numUpdatedOrDeletedRows: numAffectedRows,
        insertId:
          r.generatedFields && r.generatedFields.length > 0
            ? BigInt(r.generatedFields[0].longValue!)
            : undefined,
        rows: [],
      };
    }
    const rows = r.records
      ?.filter((r) => r.length !== 0)
      .map((rec) =>
        Object.fromEntries(
          rec.map((val, i) => {
            const { label, name, typeName } = r.columnMetadata![i];
            const key = label || name;
            let value = val.isNull
              ? null
              : val.stringValue ??
                val.doubleValue ??
                val.longValue ??
                val.booleanValue ??
                this.#unmarshallArrayValue(val.arrayValue) ??
                val.blobValue ??
                null; // FIXME: should throw an error here?

            if (typeof value === "string" && typeName) {
              const typeNameSafe = typeName.toLocaleLowerCase();
              if (["timestamp", "date"].includes(typeNameSafe)) {
                value = new Date(value);
              } else if (typeNameSafe === "timestamptz") {
                value = new Date(`${value}Z`);
              } else if (["json", "jsonb"].includes(typeNameSafe)) {
                value = JSON.parse(value);
              }
            }

            return [key, value];
          })
        )
      );

    return { rows: rows ?? [] };
  }

  async *streamQuery<O>(
    _compiledQuery: CompiledQuery,
    _chunkSize: number
  ): AsyncIterableIterator<QueryResult<O>> {
    throw new Error("Data API does not support streaming");
  }

  #unmarshallArrayValue(arrayValue: ArrayValue | undefined): unknown {
    if (!arrayValue) {
      return undefined;
    }

    return (
      arrayValue.stringValues ??
      arrayValue.doubleValues ??
      arrayValue.longValues ??
      arrayValue.booleanValues ??
      arrayValue.arrayValues?.map(this.#unmarshallArrayValue)
    );
  }
}

## Kysely Data Api

This library adds AWS RDS Data Api support for [kysely](https://github.com/koskimas/kysely). It has support for both MySQL and Postgres

### Usage

```typescript
const dataApi = new DataApiDialect({
  mode: "mysql",
  driver: {
    client: new RDSDataService(),
    database: "bench",
    secretArn: "<arn of secret containing credentials",
    resourceArn: "<arn of database>",
  },
});

export const db = new Kysely<Database>({ dialect: dataApi });
