  await reset();
});

const PERSON = {
  gender: "male",
  first_name: "jeff",
  last_name: "bezos",
} as const;

const PERSON_ALIAS = {
  first: "jeff",
  last: "bezos",
};

it("insert and read", async () => {
  await db
    .insertInto("person")
    .values(PERSON)
    .execute();

  const result = await db.selectFrom("person").selectAll().execute();
  expect(result).toHaveLength(1);
  expect(result[0]).toMatchObject(PERSON);
});

it("alias return", async () => {
  await db
    .insertInto("person")
    .values(PERSON)
    .execute();

  const result = await db
    .selectFrom("person")
    .select(["first_name as first", "last_name as last"])
    .execute();
  expect(result).toHaveLength(1);
  expect(result[0]).toMatchObject(PERSON_ALIAS);
});

it("join", async () => {
  const person = await db
    .insertInto("person")
    .values(PERSON)
    .returning(["id"])
    .executeTakeFirst();

  await db
    .insertInto("pet")
    .values({
      name: "fido",
      species: "dog",
      owner_id: person.id,
    })
    .execute();

  const result = await db
    .selectFrom("person")
    .innerJoin("pet", "pet.owner_id", "person.id")
    .select(["pet.name as pet_name", "person.first_name"])
    .executeTakeFirst();

  expect(result.first_name).toEqual("jeff");
  expect(result.pet_name).toEqual("fido");
});

it("transaction", async () => {
  await db.transaction().execute(async (tx) => {
    await tx
      .insertInto("person")
      .values(PERSON)
      .execute();
  });

  const result = await db.selectFrom("person").selectAll().execute();
  expect(result).toHaveLength(1);
  expect(result[0]).toMatchObject(PERSON);
});

import { RDSData } from "@aws-sdk/client-rds-data";
import { ColumnType, Generated, Kysely, Migrator, FileMigrationProvider } from "kysely";
import { DataApiDialect } from "../src";
import { DataApiDriverConfig } from "../src/data-api-driver";
import path from "path";
import { promises as fs } from "fs";

const TEST_DATABASE = "scratch";

const opts: DataApiDriverConfig = {
  client: new RDSData({}),
  database: TEST_DATABASE,
  secretArn: process.env.RDS_SECRET,
  resourceArn: process.env.RDS_ARN,
};
const dialect = new DataApiDialect({
  mode: "postgres",
  driver: opts,
});

export interface Person {
  avatar: Buffer;
  created_at: ColumnType<Date, never, never>;
  balance: ColumnType<string, number, number>;
  first_name: string;
  gender: "male" | "female" | "other";
  id: Generated<number>;
  is_active: boolean;
  last_name: string;
  score: bigint;
}

export interface Pet {
  id: Generated<number>;
  owner_id: number;
  name: string;
  species: "dog" | "cat";
}

// Keys are table names.
interface Database {
  person: Person;
  pet: Pet;
}

export const db = new Kysely<Database>({ dialect });

export async function migrate() {
  await opts.client
    .executeStatement({
      sql: `SELECT pg_terminate_backend(pid)
      FROM pg_stat_activity
      WHERE pid <> pg_backend_pid() AND datname = '${TEST_DATABASE}'`,
      database: "postgres",
      secretArn: opts.secretArn,
      resourceArn: opts.resourceArn,
    });

  await opts.client
    .executeStatement({
      sql: `DROP DATABASE IF EXISTS ${TEST_DATABASE}`,
      database: "postgres",
      secretArn: opts.secretArn,
      resourceArn: opts.resourceArn,
    });

  await opts.client
    .executeStatement({
      sql: `CREATE DATABASE ${TEST_DATABASE}`,
      database: "postgres",
      secretArn: opts.secretArn,
      resourceArn: opts.resourceArn,
    });

  const migrator = new Migrator({
    db,
    provider: new FileMigrationProvider({
      fs,
      path,
      migrationFolder: path.join(__dirname, "migrations"),
    }),
  })

  const { error, results } = await migrator.migrateToLatest();

  results?.forEach((it) => {
    if (it.status === "Success") {
      console.log(`migration "${it.migrationName}" was executed successfully`);
    } else if (it.status === "Error") {
      console.error(`failed to execute migration "${it.migrationName}"`);
    }
  })

  if (error) {
    console.error("failed to migrate");
    console.error(error);
  }
}

